import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Lodestone API & MCP — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"api-02-how-tos-and-workflows.md","filePath":"api-02-how-tos-and-workflows.md"}'),s={name:"api-02-how-tos-and-workflows.md"};function i(r,e,l,p,c,d){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="lodestone-api-mcp-—-how-tos-workflows" tabindex="-1">Lodestone API &amp; MCP — How-tos &amp; Workflows <a class="header-anchor" href="#lodestone-api-mcp-—-how-tos-workflows" aria-label="Permalink to &quot;Lodestone API &amp; MCP — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for generating keys and connecting external tools</em></p><hr><h2 id="generating-an-api-key" tabindex="-1">Generating an API Key <a class="header-anchor" href="#generating-an-api-key" aria-label="Permalink to &quot;Generating an API Key&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt; API &amp; MCP</strong>.</li><li>Scroll to the <strong>API Access</strong> section.</li><li>Click <strong>Generate API Key</strong>.</li><li>Give the key a name — something that identifies the tool or person it&#39;s for (e.g. &quot;ChatGPT Integration&quot;, &quot;Custom Claude Agent&quot;).</li><li>Select the scopes this key should have access to. Choose only what the integration needs (see the Scopes reference in the Overview doc).</li><li>Click <strong>Create</strong>.</li><li>The full key is displayed <strong>once</strong>. Copy it immediately and store it securely — you will not be able to retrieve it again.</li></ol><blockquote><p><strong>Important:</strong> Once you navigate away from the creation screen, the full key value is gone. If you lose it, you must revoke the key and generate a new one.</p></blockquote><hr><h2 id="revoking-an-api-key" tabindex="-1">Revoking an API Key <a class="header-anchor" href="#revoking-an-api-key" aria-label="Permalink to &quot;Revoking an API Key&quot;">​</a></h2><p>If a key is compromised, no longer needed, or you want to rotate it:</p><ol><li>Go to <strong>Settings &gt; API &amp; MCP</strong>.</li><li>Scroll to the <strong>API Access</strong> section.</li><li>Click <strong>Revoke</strong> next to the key you want to remove.</li><li>Confirm. The key is immediately invalidated — any requests using it will return <code>401 Unauthorized</code>.</li></ol><hr><h2 id="finding-your-openapi-specification" tabindex="-1">Finding Your OpenAPI Specification <a class="header-anchor" href="#finding-your-openapi-specification" aria-label="Permalink to &quot;Finding Your OpenAPI Specification&quot;">​</a></h2><p>The Lodestone API publishes an OpenAPI specification at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.lodestonepm.com/api/v1/openapi</span></span></code></pre></div><p>This specification describes every endpoint, request parameter, and response format. You can import it into:</p><ul><li><strong>ChatGPT Custom GPTs</strong> — as a custom action schema</li><li><strong>Claude Projects</strong> — as an MCP-compatible tool definition</li><li><strong>Postman, Insomnia, or any API client</strong> — for manual testing and exploration</li><li><strong>Any service that accepts OpenAPI schemas</strong></li></ul><hr><h2 id="connecting-lodestone-to-a-custom-chatgpt-custom-gpt" tabindex="-1">Connecting Lodestone to a Custom ChatGPT (Custom GPT) <a class="header-anchor" href="#connecting-lodestone-to-a-custom-chatgpt-custom-gpt" aria-label="Permalink to &quot;Connecting Lodestone to a Custom ChatGPT (Custom GPT)&quot;">​</a></h2><p>This workflow allows you to create a ChatGPT assistant that can read and act on your Lodestone workspace data.</p><h3 id="step-1-generate-an-api-key" tabindex="-1">Step 1: Generate an API key <a class="header-anchor" href="#step-1-generate-an-api-key" aria-label="Permalink to &quot;Step 1: Generate an API key&quot;">​</a></h3><p>Generate an API key with the scopes your GPT will need (see Generating an API Key above). For a read-only assistant, select all <code>:read</code> scopes. For an assistant that can create Features, add <code>features:write</code>.</p><h3 id="step-2-create-a-custom-gpt" tabindex="-1">Step 2: Create a Custom GPT <a class="header-anchor" href="#step-2-create-a-custom-gpt" aria-label="Permalink to &quot;Step 2: Create a Custom GPT&quot;">​</a></h3><ol><li><p>In ChatGPT, go to <strong>Explore GPTs</strong> &gt; <strong>Create a GPT</strong>.</p></li><li><p>In the <strong>Configure</strong> tab, give your GPT a name and instructions. Example instructions:</p><blockquote><p>&quot;You are a product management assistant connected to Lodestone. You can read and create Features, check Roadmaps, review Releases, and summarize Strategy. When the user asks about their product plans, use the Lodestone API to retrieve accurate, up-to-date information.&quot;</p></blockquote></li><li><p>Under <strong>Actions</strong>, click <strong>Create new action</strong>.</p></li></ol><h3 id="step-3-import-the-openapi-schema" tabindex="-1">Step 3: Import the OpenAPI schema <a class="header-anchor" href="#step-3-import-the-openapi-schema" aria-label="Permalink to &quot;Step 3: Import the OpenAPI schema&quot;">​</a></h3><ol><li>In the Action editor, select <strong>Import from URL</strong>.</li><li>Enter the Lodestone OpenAPI URL: <code>https://app.lodestonepm.com/api/v1/openapi</code></li><li>The schema imports and populates the available endpoints.</li></ol><h3 id="step-4-add-authentication" tabindex="-1">Step 4: Add authentication <a class="header-anchor" href="#step-4-add-authentication" aria-label="Permalink to &quot;Step 4: Add authentication&quot;">​</a></h3><ol><li>Under <strong>Authentication</strong>, select <strong>API Key</strong>.</li><li>Set the <strong>Auth Type</strong> to <strong>Bearer</strong>.</li><li>Paste your Lodestone API key.</li></ol><h3 id="step-5-test-and-save" tabindex="-1">Step 5: Test and save <a class="header-anchor" href="#step-5-test-and-save" aria-label="Permalink to &quot;Step 5: Test and save&quot;">​</a></h3><ol><li>Use the preview panel to test a request — for example, ask &quot;What features do I have in my organization?&quot;</li><li>When satisfied, save your Custom GPT.</li></ol><p>Your ChatGPT assistant can now query and act on your Lodestone workspace using natural language.</p><hr><h2 id="connecting-lodestone-to-a-claude-project" tabindex="-1">Connecting Lodestone to a Claude Project <a class="header-anchor" href="#connecting-lodestone-to-a-claude-project" aria-label="Permalink to &quot;Connecting Lodestone to a Claude Project&quot;">​</a></h2><p>This workflow allows you to create a Claude assistant with access to your Lodestone data.</p><h3 id="step-1-generate-an-api-key-1" tabindex="-1">Step 1: Generate an API key <a class="header-anchor" href="#step-1-generate-an-api-key-1" aria-label="Permalink to &quot;Step 1: Generate an API key&quot;">​</a></h3><p>Generate an API key with the scopes your Claude project will need.</p><h3 id="step-2-create-a-project-in-claude" tabindex="-1">Step 2: Create a Project in Claude <a class="header-anchor" href="#step-2-create-a-project-in-claude" aria-label="Permalink to &quot;Step 2: Create a Project in Claude&quot;">​</a></h3><ol><li><p>In Claude, create a new Project.</p></li><li><p>In the Project instructions, describe how the assistant should use Lodestone. Example:</p><blockquote><p>&quot;You have access to the Lodestone product management platform via API. Use it to retrieve Features, check Roadmap structure, and report on Release status. Always fetch current data from Lodestone rather than relying on memory.&quot;</p></blockquote></li></ol><h3 id="step-3-configure-the-lodestone-api-as-a-tool" tabindex="-1">Step 3: Configure the Lodestone API as a tool <a class="header-anchor" href="#step-3-configure-the-lodestone-api-as-a-tool" aria-label="Permalink to &quot;Step 3: Configure the Lodestone API as a tool&quot;">​</a></h3><p>Add the Lodestone API as a tool in your Project, using the OpenAPI specification URL and your API key as the bearer token.</p><h3 id="step-4-test" tabindex="-1">Step 4: Test <a class="header-anchor" href="#step-4-test" aria-label="Permalink to &quot;Step 4: Test&quot;">​</a></h3><p>Ask the assistant to retrieve your feature backlog or summarize a specific Release to confirm the connection is working.</p><hr><h2 id="making-api-requests-directly" tabindex="-1">Making API Requests Directly <a class="header-anchor" href="#making-api-requests-directly" aria-label="Permalink to &quot;Making API Requests Directly&quot;">​</a></h2><p>If you want to test the API or build a custom integration without an AI tool:</p><h3 id="list-all-features-in-an-organization" tabindex="-1">List all Features in an organization <a class="header-anchor" href="#list-all-features-in-an-organization" aria-label="Permalink to &quot;List all Features in an organization&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/features?organizationId=YOUR_ORG_ID</span></span>
<span class="line"><span>Authorization: Bearer YOUR_API_KEY</span></span></code></pre></div><h3 id="create-a-new-feature" tabindex="-1">Create a new Feature <a class="header-anchor" href="#create-a-new-feature" aria-label="Permalink to &quot;Create a new Feature&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/features</span></span>
<span class="line"><span>Authorization: Bearer YOUR_API_KEY</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;organizationId&quot;: &quot;YOUR_ORG_ID&quot;,</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;New Feature Name&quot;,</span></span>
<span class="line"><span>  &quot;description&quot;: &quot;What this feature does and why&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="list-all-releases" tabindex="-1">List all Releases <a class="header-anchor" href="#list-all-releases" aria-label="Permalink to &quot;List all Releases&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/releases?organizationId=YOUR_ORG_ID</span></span>
<span class="line"><span>Authorization: Bearer YOUR_API_KEY</span></span></code></pre></div><p>For the full list of endpoints and request/response formats, refer to the OpenAPI specification.</p><hr><h2 id="finding-your-organization-id" tabindex="-1">Finding Your Organization ID <a class="header-anchor" href="#finding-your-organization-id" aria-label="Permalink to &quot;Finding Your Organization ID&quot;">​</a></h2><p>Your Organization ID is required for most API requests. You can find it in the URL when you are logged into Lodestone:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://app.lodestonepm.com/organizations/YOUR_ORG_ID/...</span></span></code></pre></div><p>The alphanumeric string between <code>/organizations/</code> and the next <code>/</code> is your Organization ID.</p><hr><p><em>Next: Advanced Features &amp; Customization — scope strategy, multi-key management, and AI assistant design tips.</em></p>`,58)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
